def max_aggregate(data):
    # Create a dictionary to store the aggregate sum for each name
    aggregate = {}

    # Iterate over the list of tuples
    for name, value in data:
        # Add the value to the corresponding name's total
        if name in aggregate:
            aggregate[name] += value
        else:
            aggregate[name] = value

    # Find the name with the maximum aggregate value
    max_name = max(aggregate, key=aggregate.get)
    return (max_name, aggregate[max_name])

# Example usage and test case
assert max_aggregate([('Juan Whelan',90),('Sabah Colley',88),('Peter Nichols',7),('Juan Whelan',122),('Sabah Colley',84)]) == ('Juan Whelan', 212)
```

