def find_kth(arr1, arr2, k):
    def kth_element(a, b, k):
        if not a:
            return b[k - 1]
        if not b:
            return a[k - 1]
        if k == 1:
            return min(a[0], b[0])

        idx_a = min(len(a), k // 2)
        idx_b = min(len(b), k // 2)

        if a[idx_a - 1] <= b[idx_b - 1]:
            return kth_element(a[idx_a:], b, k - idx_a)
        else:
            return kth_element(a, b[idx_b:], k - idx_b)

    return kth_element(arr1, arr2, k)

# Example usage with assertion:
assert find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5) == 6
```

