def recursive_list_sum(data):
    def flatten_and_sum(lst):
        total = 0
        for item in lst:
            if isinstance(item, list):
                total += flatten_and_sum(item)
            else:
                total += item
        return total
    return flatten_and_sum(data)

# Example use case
assert recursive_list_sum([1, 2, [3, 4], [5, 6]]) == 21
