def merge_dictionaries_three(dict1, dict2, dict3):
    # Merge the dictionaries into a single one, resolving conflicts by preserving the first occurrence
    merged_dict = dict1.copy()  # Start with the first dictionary
    for d in [dict2, dict3]:
        for key, value in d.items():
            if key not in merged_dict:  # Only add the key if it's not already present
                merged_dict[key] = value
    return merged_dict

# Example usage and tests
assert merge_dictionaries_three(
    {"R": "Red", "B": "Black", "P": "Pink"},
    {"G": "Green", "W": "White"},
    {"O": "Orange", "W": "White", "B": "Black"}
) == {'B': 'Black', 'R': 'Red', 'P': 'Pink', 'G': 'Green', 'W': 'White', 'O': 'Orange'}

assert merge_dictionaries_three(
    {"R": "Red", "B": "Black", "P": "Pink"},
    {"G": "Green", "W": "White"},
    {"L": "lavender", "B": "Blue"}
) == {'R': 'Red', 'B': 'Black', 'P': 'Pink', 'G': 'Green', 'W': 'White', 'L': 'lavender'}
